def totals_per_customer(db, orders):
    totals = {}
    for order in orders:
        row = db.execute("SELECT SUM(price) FROM items WHERE order_id = ?", (order["id"],)).fetchone()
        totals[order["customer"]] = totals.get(order["customer"], 0) + (row[0] or 0)
    return totals


def totals_batched(db, orders):
    ids = [o["id"] for o in orders]
    marks = ",".join("?" for _ in ids)
    rows = db.execute(f"SELECT order_id, SUM(price) FROM items WHERE order_id IN ({marks}) GROUP BY order_id", ids).fetchall()
    return dict(rows)


def count_orders(db):
    return db.execute("SELECT COUNT(*) FROM orders").fetchone()[0]


def match_stock(items, stock):
    matched = []
    for item in items:
        for entry in stock:
            if entry["sku"] == item["sku"]:
                matched.append((item, entry))
    return matched
